(()=>{
 const login=document.querySelector('#admin-login-form');if(!login)return;
 const status=document.querySelector('#admin-status'),panel=document.querySelector('#admin-panel'),section=document.querySelector('#admin-section'),item=document.querySelector('#admin-item'),fields=document.querySelector('#admin-fields');let content,sha,busy=false,activeRow=null,activeSection='',pendingUploads=0,pollTimer=null;
 const dirty=new Set(),fresh=new WeakSet();let publishedCovers={};
 const definitions={books:[['number','Numéro','number'],['title','Titre'],['available','Livre paru','checkbox'],['release_month','Mois de parution prévu','month'],['price','Prix (€)','number'],['pages','Nombre de pages','number'],['isbn','ISBN'],['commande_url','Lien du produit SumUp'],['color','Couleur','color']],events:[['title','Nom de la rencontre'],['start_date','Date de début','date'],['end_date','Date de fin (facultative)','date'],['city','Ville'],['place','Salle ou lieu'],['street','Adresse'],['postal_code','Code postal'],['confirmed','Informations confirmées','checkbox'],['description','Présentation','textarea']],stores:[['name','Nom du point de vente'],['address','Adresse'],['postal_code','Code postal'],['city','Ville'],['phone','Téléphone'],['url','Site internet']],subscription:[['min_books','Nombre minimal d’exemplaires','number'],['max_books','Nombre maximal d’exemplaires','number']]};
 const button=document.querySelector('#admin-publish');
 function updateButton(){button.disabled=busy||pendingUploads>0;document.querySelector('#admin-dirty').textContent=dirty.size?'Modifications non publiées : '+[...dirty].map(s=>({books:'livres',events:'rencontres',stores:'points de vente',subscription:'abonnement'}[s])).join(', '):'Aucune modification en attente.';}
 function changed(s){dirty.add(s);updateButton();}
 async function call(body){const r=await fetch('/api/admin',{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',signal:AbortSignal.timeout(55000)});let answer;try{answer=await r.json();}catch{throw Error('Administration indisponible. Vérifiez que la dernière version est déployée sur Vercel.');}if(!r.ok)throw Error(answer.error||'Opération impossible.');return answer;}
 function entries(){return content[section.value]||(content[section.value]=[]);}
 function slug(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'element';}
 function capture(){const row=activeRow;if(!row)return;for(const [key,,type] of definitions[activeSection]){const input=fields.querySelector(`[name="${key}"]`);if(input)row[key]=type==='checkbox'?input.checked:type==='number'?Number(input.value):input.value;}if(activeSection==='books')row.status=row.available?'paru':row.release_month?'prochain':'plus_tard';if(fresh.has(row)&&activeSection!=='subscription'){const base=slug(row.title||row.name);let candidate=base,i=2;const others=content[activeSection].filter(x=>x!==row);while(others.some(x=>x.slug===candidate))candidate=base+'-'+i++;row.slug=candidate;}changed(activeSection);const option=item.selectedOptions[0];if(option)option.textContent=row.title||row.name||row.slug;status.textContent='Modifications préparées. Cliquez sur Publier pour les enregistrer.';}
 async function compress(file,limit=155000,max=1400){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>20*1024*1024)throw Error('Choisissez une image JPEG, PNG ou WebP de moins de 20 Mo.');const image=await createImageBitmap(file);try{const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');let size=Math.min(1,max/Math.max(image.width,image.height));for(let attempt=0;attempt<7;attempt++){canvas.width=Math.round(image.width*size);canvas.height=Math.round(image.height*size);ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',Math.max(.65,.9-attempt*.04));if(data.length<=limit)return data;size*=.86;}throw Error('Cette image reste trop lourde. Réduisez ses dimensions.');}finally{image.close();}}
 function media(row,key,label,multiple=false){const box=document.createElement('div');box.className='admin-media';const h=document.createElement('h3');h.textContent=label;box.append(h);const file=document.createElement('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';file.multiple=multiple;file.setAttribute('aria-label',label);const preview=document.createElement('div');preview.className='admin-media-list';const note=document.createElement('p');note.className='admin-note';note.textContent=multiple?'Sélectionnez jusqu’à 4 images, dans l’ordre de lecture. Elles remplacent le feuilletage existant.':'L’image est optimisée automatiquement. Vérifiez l’aperçu puis publiez.';
 function show(){preview.replaceChildren();const source=row[key]||(key==='cover'&&!row.cover_hidden?publishedCovers[row.number]:'');const list=multiple?(row[key]||[]):source?[source]:[];for(const [i,src] of list.entries()){const figure=document.createElement('figure'),img=document.createElement('img');img.src=src;img.alt=multiple?'Page '+(i+1):label;figure.append(img);if(multiple){const number=document.createElement('figcaption');number.textContent='Page '+(i+1);figure.append(number);if(i>0){const prev=document.createElement('button');prev.type='button';prev.textContent='← Déplacer';prev.addEventListener('click',()=>{[row[key][i-1],row[key][i]]=[row[key][i],row[key][i-1]];changed(activeSection);show();});figure.append(prev);}}const remove=document.createElement('button');remove.type='button';remove.textContent='Retirer';remove.addEventListener('click',()=>{if(multiple)row[key].splice(i,1);else {row[key]='';if(key==='cover')row.cover_hidden=true;}changed(activeSection);show();});figure.append(remove);preview.append(figure);}}
 file.addEventListener('change',async()=>{const chosen=[...file.files];if(!chosen.length)return;if(multiple&&chosen.length>4){status.textContent='Sélectionnez 4 images au maximum.';return;}const targetSection=activeSection;pendingUploads++;updateButton();status.textContent='Préparation des images…';try{const result=[];for(const selected of chosen)result.push(await compress(selected,multiple?165000:190000,multiple?1600:1200));row[key]=multiple?result:result[0];if(key==='cover')row.cover_hidden=false;changed(targetSection);show();status.textContent='Images prêtes. Cliquez sur Publier pour les enregistrer.';}catch(error){status.textContent=error.message;}finally{pendingUploads--;file.value='';updateButton();}});box.append(file,note,preview);show();fields.append(box);}
 function render(){fields.replaceChildren();activeSection=section.value;activeRow=activeSection==='subscription'?(content.subscription||(content.subscription={min_books:3,max_books:12,max_parcel:3})):entries()[Number(item.value)];const row=activeRow;if(!row){const p=document.createElement('p');p.className='admin-empty';p.textContent='Aucun élément. Cliquez sur Ajouter, ou Publier pour confirmer le retrait du dernier élément.';fields.append(p);return;}
 for(const [key,label,type] of definitions[activeSection]){const wrapper=document.createElement('label');wrapper.textContent=label;const input=document.createElement(type==='textarea'?'textarea':'input');input.name=key;if(type!=='textarea')input.type=type||'text';if(type==='number'){input.step=key==='price'?'0.01':'1';input.min=key==='price'?'0.01':'1';}if(type==='checkbox')input.checked=row[key]===true;else input.value=row[key]??'';if(type==='textarea'){input.rows=4;wrapper.className='full';}wrapper.append(input);fields.append(wrapper);}
 if(activeSection==='books'){media(row,'cover','Couverture');media(row,'excerpts','Pages à feuilleter',true);}if(activeSection==='events')media(row,'image','Photo de la rencontre');
 }
 function choose(index=0){document.querySelector('#admin-item-tools').hidden=section.value==='subscription';item.replaceChildren();if(section.value!=='subscription')entries().forEach((row,i)=>{const option=document.createElement('option');option.value=i;option.textContent=row.title||row.name||row.slug;item.append(option);});if(item.options.length)item.value=String(Math.min(index,item.options.length-1));render();}
 async function load(){const answer=await call();content=answer.content;publishedCovers=Object.fromEntries((answer.media||[]).map(b=>[b.number,b.cover]));sha=answer.sha;dirty.clear();panel.hidden=false;document.querySelector('#admin-login').hidden=true;choose();updateButton();status.textContent='Contenus chargés depuis GitHub.';}
 function watch(hash){clearTimeout(pollTimer);let count=0;async function check(){try{const r=await fetch('/publication.json?t='+Date.now(),{cache:'no-store'});const p=await r.json();if(p.catalog_hash===hash){status.textContent='Publication terminée : les modifications sont visibles sur le site.';return;}}catch{}if(++count<36){pollTimer=setTimeout(check,5000);}else status.textContent='Enregistré dans GitHub, mais la nouvelle version n’est pas encore visible. Vérifiez le projet sitelpgrapp dans Vercel → Deployments et sa connexion au dépôt site_lpgrapp. Ne republiez pas les mêmes changements.';}pollTimer=setTimeout(check,4000);}
 login.addEventListener('submit',async e=>{e.preventDefault();try{await call({action:'login',password:document.querySelector('#admin-password').value});document.querySelector('#admin-password').value='';await load();}catch(error){status.textContent=error.message;}});
 fields.addEventListener('input',capture);fields.addEventListener('change',capture);section.addEventListener('change',()=>choose());item.addEventListener('change',render);
 document.querySelector('#admin-add').addEventListener('click',()=>{const rows=entries(),row=section.value==='books'?{number:Math.max(0,...rows.map(x=>x.number))+1,title:'Nouveau livre',slug:'nouveau-'+Date.now(),available:false,price:15,pages:24,color:'#704575',description:'',cover:'',excerpts:[],release_month:'',isbn:'',commande_url:''}:section.value==='events'?{slug:'nouvelle-rencontre-'+Date.now(),title:'Nouvelle rencontre',start_date:'',city:'',place:'',confirmed:true}:{slug:'nouveau-point-'+Date.now(),name:'Nouveau point de vente',address:'',city:'',phone:'',url:''};fresh.add(row);rows.push(row);changed(section.value);choose(rows.length-1);status.textContent='Élément ajouté. Complétez-le puis publiez.';});
 document.querySelector('#admin-delete').addEventListener('click',()=>{const rows=entries();if(!activeRow)return;if(!confirm('Retirer cet élément du site ? Cliquez ensuite sur Publier pour confirmer.'))return;const name=activeRow.title||activeRow.name;rows.splice(Number(item.value),1);changed(section.value);choose();status.textContent=name+' retiré de la liste. Cliquez sur Publier pour le supprimer du site.';});
 document.querySelector('#admin-editor').addEventListener('submit',async e=>{e.preventDefault();if(busy||pendingUploads)return;if(!dirty.size){status.textContent='Aucune modification à publier.';return;}busy=true;updateButton();status.textContent='Enregistrement dans GitHub…';try{const sections=Object.fromEntries([...dirty].map(s=>[s,content[s]]));const answer=await call({action:'save',sections,sha});sha=answer.sha;dirty.clear();for(const row of content.books||[])fresh.delete(row);for(const row of content.events||[])fresh.delete(row);for(const row of content.stores||[])fresh.delete(row);status.textContent=answer.message;if(answer.catalog_hash)watch(answer.catalog_hash);}catch(error){status.textContent=error.message;}finally{busy=false;updateButton();}});
 document.querySelector('#admin-reload').addEventListener('click',()=>{if(dirty.size&&!confirm('Recharger et abandonner les modifications non publiées ?'))return;load().catch(e=>status.textContent=e.message);});document.querySelector('#admin-logout').addEventListener('click',async()=>{try{await call({action:'logout'});location.reload();}catch(error){status.textContent=error.message;}});window.addEventListener('beforeunload',e=>{if(dirty.size||pendingUploads){e.preventDefault();e.returnValue='';}});load().catch(error=>{panel.hidden=true;status.textContent=error.message;});
})();
